+fn run() -> u8 {
+    let mut args: Vec<String> = env::args().skip(1).collect();
+    if args.is_empty() {
+        print!("{TOP_HELP}");
+        return 2;
+    }
+
+    let first = args.remove(0);
+    if matches!(first.as_str(), "-h" | "--help") {
+        print!("{TOP_HELP}");
+        return 0;
+    }
+    if first == "help" {
+        if args.is_empty() {
+            print!("{TOP_HELP}");
+            return 0;
+        }
+        if let Some(cmd) = canonical_command(&args[0]) {
+            print!("{}", command_help(cmd));
+            return 0;
+        }
+        print!("{TOP_HELP}");
+        return 0;
+    }
+
+    let Some(cmd) = canonical_command(&first) else {
+        print_unknown_top_level(&first);
+        return 2;
+    };
+
+    if matches!(args.first().map(String::as_str), Some("-h" | "--help")) {
+        print!("{}", command_help(cmd));
+        return 0;
+    }
+
+    match cmd {
+        Cmd::Vault => dispatch_vault(args),
+        Cmd::Enter => dispatch_enter(args),
+        Cmd::Note => dispatch_note(args),
+        Cmd::Folder => dispatch_folder(args),
+        Cmd::Open => dispatch_open(args),
+        Cmd::OpDir => dispatch_opdir(args),
+        Cmd::Chdir => dispatch_chdir(args),
+        Cmd::List => dispatch_list(args),
+        Cmd::Remove => dispatch_remove(args),
+        Cmd::Rename => dispatch_rename(args),
+        Cmd::Move => dispatch_move(args),
+        Cmd::VMove => dispatch_vmove(args),
+        Cmd::Config => dispatch_config(args),
+    }
+}
