+fn dispatch_vault(args: Vec<String>) -> u8 {
+    match args.as_slice() {
+        [] => {
+            let Some(state) = load_state() else {
+                return 0;
+            };
+            print_vaults(&state, false);
+            0
+        }
+        [flag] if flag == "-l" => {
+            let Some(state) = load_state() else {
+                return 0;
+            };
+            print_vaults(&state, true);
+            0
+        }
+        [name] => {
+            print_missing_required(&["vault location"], vault_usage_lines());
+            let _ = name;
+            2
+        }
+        [name, location] => {
+            let Some(mut state) = load_state() else {
+                return 0;
+            };
+            if !Path::new(location).is_absolute() {
+                runtime_error("specified path isn't absolute");
+                return 0;
+            }
+            if state.find_vault(name).is_some() {
+                runtime_error(format!("vault {name} already exists"));
+                return 0;
+            }
+            let vault_root = PathBuf::from(location).join(name);
+            if vault_root.exists() {
+                runtime_error(format!(
+                    "a folder named {name} already exists in this location"
+                ));
+                return 0;
+            }
+            if let Err(err) = fs::create_dir_all(vault_root.join(".jot")) {
+                runtime_error(err.to_string());
+                return 0;
+            }
+            let data = VaultData {
+                name: name.clone(),
+                location: location.clone(),
+                folder: String::new(),
+            };
+            if let Err(err) = write_vault_data(&vault_root.join(".jot").join("data"), &data) {
+                runtime_error(err.to_string());
+                return 0;
+            }
+            state.insert_vault_front(VaultEntry {
+                name: name.clone(),
+                location: location.clone(),
+            });
+            if let Err(err) = state.save_vaults() {
+                runtime_error(err.to_string());
+                return 0;
+            }
+            println!("vault {} created", blue(name));
+            0
+        }
+        _ => {
+            print_unknown_argument(args.last().expect("extra arg"));
+            2
+        }
+    }
+}
