+fn dispatch_enter(args: Vec<String>) -> u8 {
+    let [name] = exact_slice::<1>(&args) else {
+        return missing_for_count(args.len(), &["vault name"], enter_usage_lines());
+    };
+    let Some(mut state) = load_state() else {
+        return 0;
+    };
+    if state.find_vault(name).is_none() {
+        runtime_error(format!("vault {name} doesn't exist"));
+        return 0;
+    }
+    state.vaults.current = Some(name.clone());
+    state.move_vault_to_front(name);
+    if let Err(err) = state.save_vaults() {
+        runtime_error(err.to_string());
+        return 0;
+    }
+    println!("entered {}", blue(name));
+    0
+}
