+        [kind] => match parse_list_filter(kind) {
+            Some(filter) => Some(filter),
+            None => {
+                print_invalid_value(kind, "item type", &["note", "nt", "folder", "fd"]);
+                return 2;
+            }
+        },
+        _ => {
+            print_unknown_argument(args.last().expect("extra arg"));
+            return 2;
+        }
+    };
+
+    let Some(state) = load_state() else {
+        return 0;
+    };
+    let Some(current) = current_or_error(&state) else {
+        return 0;
+    };
+
+    let label = folder_label(&current.data);
+    println!("{label}");
+    match filter {
+        None => list_recursive(&current.current_dir, ""),
+        Some(ListFilter::Note) => list_shallow(&current.current_dir, ListFilter::Note),
+        Some(ListFilter::Folder) => list_shallow(&current.current_dir, ListFilter::Folder),
+    }
+    0
+}
