+fn dispatch_move(args: Vec<String>) -> u8 {
+    let Some((kind, name, new_location)) =
+        parse_item_dispatch(&args, move_usage_lines(), &["item type", "name", "new location"])
+    else {
+        return 2;
+    };
+    let Some(mut state) = load_state() else {
+        return 0;
+    };
+
+    match kind {
+        ItemKind::Vault => {
+            let Some(entry) = state.find_vault(&name).cloned() else {
+                runtime_error(format!("vault {name} doesn't exist"));
+                return 0;
+            };
+            if !Path::new(&new_location).is_absolute() {
+                runtime_error("specified path isn't absolute");
+                return 0;
+            }
+            let source = PathBuf::from(&entry.location).join(&entry.name);
+            let target = PathBuf::from(&new_location).join(&entry.name);
+            if let Err(err) = fs::rename(&source, &target) {
+                runtime_error(err.to_string());
+                return 0;
+            }
+            if let Some(entry_mut) = state.find_vault_mut(&name) {
+                entry_mut.location = new_location.clone();
+            }
+            if let Err(err) = state.save_vaults() {
+                runtime_error(err.to_string());
+                return 0;
+            }
+            let mut data = read_vault_data(&target.join(".jot").join("data")).unwrap_or(VaultData {
+                name: name.clone(),
+                location: new_location.clone(),
+                folder: String::new(),
+            });
+            data.location = new_location.clone();
+            if let Err(err) = write_vault_data(&target.join(".jot").join("data"), &data) {
+                runtime_error(err.to_string());
+                return 0;
+            }
+            println!("vault {} moved", blue(&name));
+        }
+        ItemKind::Note => {
+            let Some(current) = current_or_error(&state) else {
+                return 0;
+            };
+            let target_dir = resolve_path(&current.current_dir, &new_location);
+            if !target_dir.exists() {
+                runtime_error("couldn't find the path specified");
+                return 0;
+            }
+            if !within_root(&current.root, &target_dir) {
+                runtime_error("path crosses the bounds of vault");
+                return 0;
+            }
+            let destination = target_dir.join(format!("{name}.md"));
+            if destination.exists() {
+                runtime_error(format!("a note named {name} already exists in this location"));
+                return 0;
+            }
+            let source = current.current_dir.join(format!("{name}.md"));
+            if let Err(err) = fs::rename(source, destination) {
+                runtime_error(err.to_string().to_lowercase());
+                return 0;
+            }
+            println!("note {} moved", blue(&name));
+        }
+        ItemKind::Folder => {
+            let Some(current) = current_or_error(&state) else {
+                return 0;
+            };
+            let target_dir = resolve_path(&current.current_dir, &new_location);
+            if !target_dir.exists() {
+                runtime_error("couldn't find the path specified");
+                return 0;
+            }
+            if !within_root(&current.root, &target_dir) {
+                runtime_error("path crosses the bounds of vault");
+                return 0;
+            }
+            let destination = target_dir.join(&name);
+            if destination.exists() {
+                runtime_error(format!(
+                    "a folder named {name} already exists in this location"
+                ));
+                return 0;
+            }
+            let source = current.current_dir.join(&name);
+            if let Err(err) = fs::rename(source, destination) {
+                runtime_error(err.to_string().to_lowercase());
+                return 0;
+            }
+            println!("folder {} moved", blue(&name));
+        }
+    }
+    0
+}
