impl AppState {
    fn load() -> io::Result<Self> {
        let home = real_home_dir()?;
        let config_dir = home.join(".config").join("jot");
        let share_dir = home.join(".local").join("share").join("jot");
        fs::create_dir_all(&config_dir)?;
        fs::create_dir_all(&share_dir)?;

        let config_path = config_dir.join("config");
        let vaults_path = share_dir.join("vaults");

        if !config_path.exists() {
            write_config(&config_path, &Config::default())?;
        }
        if !vaults_path.exists() {
            fs::write(&vaults_path, "[vaults]\n")?;
        }

        let config = read_config(&config_path)?;
        let vaults = read_vaults(&vaults_path)?;

        Ok(Self {
            config_path,
            vaults_path,
            config,
            vaults,
        })
    }

    fn save_config(&self) -> io::Result<()> {
        write_config(&self.config_path, &self.config)
    }

    fn save_vaults(&self) -> io::Result<()> {
        write_vaults(&self.vaults_path, &self.vaults)
    }

    fn find_vault(&self, name: &str) -> Option<&VaultEntry> {
        self.vaults.entries.iter().find(|entry| entry.name == name)
    }

    fn find_vault_mut(&mut self, name: &str) -> Option<&mut VaultEntry> {
        self.vaults
            .entries
            .iter_mut()
            .find(|entry| entry.name == name)
    }

    fn insert_vault_front(&mut self, entry: VaultEntry) {
        self.vaults.entries.retain(|existing| existing.name != entry.name);
        self.vaults.entries.insert(0, entry);
    }

    fn move_vault_to_front(&mut self, name: &str) {
        if let Some(index) = self
            .vaults
            .entries
            .iter()
            .position(|entry| entry.name == name)
        {
            let entry = self.vaults.entries.remove(index);
            self.vaults.entries.insert(0, entry);
        }
    }

    fn remove_vault(&mut self, name: &str) {
        self.vaults.entries.retain(|entry| entry.name != name);
        if self.vaults.current.as_deref() == Some(name) {
            self.vaults.current = None;
        }
    }

    fn current_vault(&self) -> io::Result<Option<CurrentVault>> {
        let Some(current) = self.vaults.current.as_ref() else {
            return Ok(None);
        };
        let Some(entry) = self.find_vault(current).cloned() else {
            return Ok(None);
        };
        let root = PathBuf::from(&entry.location).join(&entry.name);
        let data = read_vault_data(&root.join(".jot").join("data"))?;
        let current_dir = if data.folder.is_empty() {
            root.clone()
        } else {
            root.join(&data.folder)
        };
