fn run() -> u8 {
    let mut args: Vec<String> = env::args().skip(1).collect();
    if args.is_empty() {
        print!("{TOP_HELP}");
        return 2;
    }

    let first = args.remove(0);
    if matches!(first.as_str(), "-h" | "--help") {
        print!("{TOP_HELP}");
        return 0;
    }
    if first == "help" {
        if args.is_empty() {
            print!("{TOP_HELP}");
            return 0;
        }
        if let Some(cmd) = canonical_command(&args[0]) {
            print!("{}", command_help(cmd));
            return 0;
        }
        print!("{TOP_HELP}");
        return 0;
    }

    let Some(cmd) = canonical_command(&first) else {
        print_unknown_top_level(&first);
        return 2;
    };

    if matches!(args.first().map(String::as_str), Some("-h" | "--help")) {
        print!("{}", command_help(cmd));
        return 0;
    }

    match cmd {
        Cmd::Vault => dispatch_vault(args),
        Cmd::Enter => dispatch_enter(args),
        Cmd::Note => dispatch_note(args),
        Cmd::Folder => dispatch_folder(args),
        Cmd::Open => dispatch_open(args),
        Cmd::OpDir => dispatch_opdir(args),
        Cmd::Chdir => dispatch_chdir(args),
        Cmd::List => dispatch_list(args),
        Cmd::Remove => dispatch_remove(args),
        Cmd::Rename => dispatch_rename(args),
        Cmd::Move => dispatch_move(args),
        Cmd::VMove => dispatch_vmove(args),
        Cmd::Config => dispatch_config(args),
    }
}

fn dispatch_vault(args: Vec<String>) -> u8 {
    match args.as_slice() {
        [] => {
            let Some(state) = load_state() else {
                return 0;
            };
            print_vaults(&state, false);
            0
        }
        [flag] if flag == "-l" => {
            let Some(state) = load_state() else {
                return 0;
            };
            print_vaults(&state, true);
            0
        }
        [name] => {
            print_missing_required(&["vault location"], vault_usage_lines());
            let _ = name;
            2
        }
        [name, location] => {
            let Some(mut state) = load_state() else {
                return 0;
            };
            if !Path::new(location).is_absolute() {
                runtime_error("specified path isn't absolute");
                return 0;
            }
            if state.find_vault(name).is_some() {
                runtime_error(format!("vault {name} already exists"));
                return 0;
            }
            let vault_root = PathBuf::from(location).join(name);
            if vault_root.exists() {
                runtime_error(format!(
                    "a folder named {name} already exists in this location"
                ));
                return 0;
            }
            if let Err(err) = fs::create_dir_all(vault_root.join(".jot")) {
                runtime_error(err.to_string());
                return 0;
            }
            let data = VaultData {
                name: name.clone(),
                location: location.clone(),
                folder: String::new(),
            };
            if let Err(err) = write_vault_data(&vault_root.join(".jot").join("data"), &data) {
                runtime_error(err.to_string());
                return 0;
            }
            state.insert_vault_front(VaultEntry {
                name: name.clone(),
                location: location.clone(),
            });
            if let Err(err) = state.save_vaults() {
                runtime_error(err.to_string());
                return 0;
            }
            println!("vault {} created", blue(name));
            0
        }
        _ => {
            print_unknown_argument(args.last().expect("extra arg"));
            2
        }
    }
}

