fn dispatch_rename(args: Vec<String>) -> u8 {
    let Some((kind, name, new_name)) =
        parse_item_dispatch(&args, rename_usage_lines(), &["item type", "name", "new name"])
    else {
        return 2;
    };
    let Some(mut state) = load_state() else {
        return 0;
    };
    if name == new_name {
        runtime_error("new name is same as old name");
        return 0;
    }

    match kind {
        ItemKind::Vault => {
            let Some(entry) = state.find_vault(&name).cloned() else {
                runtime_error(format!("vault {name} doesn't exist"));
                return 0;
            };
            let source = PathBuf::from(&entry.location).join(&entry.name);
            let target = PathBuf::from(&entry.location).join(&new_name);
            if let Err(err) = fs::rename(&source, &target) {
                runtime_error(err.to_string());
                return 0;
            }
            if let Some(entry_mut) = state.find_vault_mut(&name) {
                entry_mut.name = new_name.clone();
            }
            if state.vaults.current.as_deref() == Some(name.as_str()) {
                state.vaults.current = Some(new_name.clone());
            }
            if let Err(err) = state.save_vaults() {
                runtime_error(err.to_string());
                return 0;
            }
            let data = VaultData {
                name: new_name.clone(),
                location: entry.location.clone(),
                folder: read_vault_data(&target.join(".jot").join("data"))
                    .map(|data| data.folder)
                    .unwrap_or_default(),
            };
            if let Err(err) = write_vault_data(&target.join(".jot").join("data"), &data) {
                runtime_error(err.to_string());
                return 0;
            }
            println!("vault {} renamed to {}", blue(&name), blue(&new_name));
        }
        ItemKind::Note => {
            let Some(current) = current_or_error(&state) else {
                return 0;
            };
            let source = current.current_dir.join(format!("{name}.md"));
            if !source.exists() {
                runtime_error(format!("note {name} not found"));
                return 0;
            }
            let target = current.current_dir.join(format!("{new_name}.md"));
            if let Err(err) = fs::rename(source, target) {
                runtime_error(err.to_string());
                return 0;
            }
            println!("note {} renamed to {}", blue(&name), blue(&new_name));
        }
        ItemKind::Folder => {
            let Some(current) = current_or_error(&state) else {
                return 0;
            };
            let source = current.current_dir.join(&name);
            if !source.exists() {
                runtime_error(format!("folder {name} not found"));
                return 0;
            }
            let target = current.current_dir.join(&new_name);
            if let Err(err) = fs::rename(source, target) {
                runtime_error(err.to_string());
                return 0;
            }
            println!("folder {} renamed to {}", blue(&name), blue(&new_name));
        }
    }
    0
}

