fn print_vaults(state: &AppState, with_locations: bool) {
    if let Some(current) = state.vaults.current.as_deref() {
        if with_locations {
            if let Some(current_entry) = state.find_vault(current) {
                println!(
                    "👉 {} \t {}",
                    blue(&current_entry.name),
                    current_entry.location
                );
            }
            for entry in &state.vaults.entries {
                if entry.name != current {
                    println!("   {} \t {}", entry.name, entry.location);
                }
            }
        } else {
            for entry in &state.vaults.entries {
                if entry.name != current {
                    println!("   {}", entry.name);
                }
            }
            if state.find_vault(current).is_some() {
                println!("👉 {}", blue(current));
            }
        }
        return;
    }

    for entry in &state.vaults.entries {
        if with_locations {
            println!("   {} \t {}", entry.name, entry.location);
        } else {
            println!("   {}", entry.name);
        }
    }
}

fn list_recursive(dir: &Path, prefix: &str) {
    let Ok(entries) = read_entries(dir) else {
        return;
    };
    let total = entries.len();
    for (index, entry) in entries.iter().enumerate() {
        let is_last = index + 1 == total;
        let child_prefix = if is_last {
            format!("{prefix}    ")
        } else {
            format!("{prefix}│   ")
        };
        let file_name = entry.file_name().to_string_lossy().to_string();
        let path = entry.path();
        let Ok(file_type) = entry.file_type() else {
            continue;
        };

        if file_type.is_file() {
            if let Some(note_name) = note_name(&file_name) {
                println!(
                    "{}{} {}",
                    prefix,
                    if is_last { "└──" } else { "├──" },
                    blue(note_name)
                );
            }
            continue;
        }

        if !file_type.is_dir() {
            continue;
        }

        if !file_name.starts_with('.') {
            println!(
                "{}{} {}",
                prefix,
                if is_last { "└──" } else { "├──" },
                file_name
            );
            list_recursive(&path, &child_prefix);
        }
    }
}

fn list_shallow(dir: &Path, filter: ListFilter) {
    let Ok(entries) = read_entries(dir) else {
        return;
    };
    let mut filtered = Vec::new();
    for entry in entries {
        let file_name = entry.file_name().to_string_lossy().to_string();
        let Ok(file_type) = entry.file_type() else {
            continue;
        };
        match filter {
            ListFilter::Note if file_type.is_file() => {
                if let Some(note_name) = note_name(&file_name) {
                    filtered.push((true, note_name.to_string()));
                }
            }
            ListFilter::Folder if file_type.is_dir() => {
                filtered.push((false, file_name));
            }
            _ => {}
        }
    }
    let total = filtered.len();
    for (index, (is_note, name)) in filtered.into_iter().enumerate() {
        let glyph = if index + 1 == total { "└──" } else { "├──" };
        if is_note {
            println!("{glyph} {}", blue(&name));
        } else {
            println!("{glyph} {name}");
        }
    }
}

fn folder_label(data: &VaultData) -> String {
    if data.folder.is_empty() {
        data.name.clone()
    } else {
        let suffix = data.folder.split('/').collect::<Vec<_>>().join(" > ");
        format!("{} > {}", data.name, suffix)
    }
}

fn read_entries(dir: &Path) -> io::Result<Vec<fs::DirEntry>> {
    let mut entries = Vec::new();
    for entry in fs::read_dir(dir)? {
        entries.push(entry?);
    }
    Ok(entries)
}

fn note_name(file_name: &str) -> Option<&str> {
    file_name.strip_suffix(".md")
}

fn resolve_path(base: &Path, path: &str) -> PathBuf {
    let joined = if Path::new(path).is_absolute() {
        PathBuf::from(path)
    } else {
        base.join(path)
    };
    normalize_path(&joined)
}

fn normalize_path(path: &Path) -> PathBuf {
    let mut parts = Vec::new();
    let absolute = path.is_absolute();

    for component in path.components() {
        match component {
            Component::RootDir => {}
            Component::CurDir => {}
            Component::ParentDir => {
                if !parts.is_empty() {
                    parts.pop();
                } else if !absolute {
                    parts.push("..".to_string());
                }
            }
            Component::Normal(part) => parts.push(part.to_string_lossy().to_string()),
            Component::Prefix(_) => {}
        }
    }

    let mut normalized = if absolute {
        PathBuf::from("/")
    } else {
        PathBuf::new()
    };
    for part in parts {
        normalized.push(part);
    }
    normalized
}

fn within_root(root: &Path, path: &Path) -> bool {
    path == root || path.starts_with(root)
}

fn relative_folder(root: &Path, dir: &Path) -> String {
    match dir.strip_prefix(root) {
        Ok(relative) => relative
            .components()
            .filter_map(|component| match component {
                Component::Normal(part) => Some(part.to_string_lossy().to_string()),
                _ => None,
            })
            .collect::<Vec<_>>()
            .join("/"),
        Err(_) => String::new(),
    }
}

fn parse_item_dispatch(
    args: &[String],
    usage: &[&str],
    required: &[&str],
) -> Option<(ItemKind, String, String)> {
    match args {
        [] => {
            print_missing_required(required, usage);
            None
        }
        [kind] => {
            print_missing_required(&required[1..], usage);
            let _ = kind;
            None
        }
        [kind, name] if required.len() == 3 => {
            let item_kind = match parse_item_kind(kind, true) {
                Some(item_kind) => item_kind,
                None => {
                    print_invalid_value(
                        kind,
                        "item type",
                        &["vault", "vl", "note", "nt", "folder", "fd"],
                    );
                    return None;
                }
            };
            Some((item_kind, name.clone(), String::new()))
        }
        [kind, name, value] => {
            let item_kind = match parse_item_kind(kind, true) {
                Some(item_kind) => item_kind,
                None => {
                    print_invalid_value(
                        kind,
                        "item type",
                        &["vault", "vl", "note", "nt", "folder", "fd"],
                    );
                    return None;
                }
            };
            Some((item_kind, name.clone(), value.clone()))
        }
        _ => {
            print_unknown_argument(args.last().expect("extra arg"));
            None
        }
    }
}

fn parse_item_dispatch_no_vaults(
    args: &[String],
    usage: &[&str],
    required: &[&str],
) -> Option<(ItemKind, String, String)> {
    match args {
        [] => {
            print_missing_required(required, usage);
            None
        }
        [kind] => {
            print_missing_required(&required[1..], usage);
            let _ = kind;
            None
        }
        [kind, name] => {
            print_missing_required(&required[2..], usage);
            let _ = (kind, name);
            None
        }
        [kind, name, vault_name] => {
            let item_kind = match parse_item_kind(kind, false) {
                Some(item_kind) => item_kind,
                None => {
                    print_invalid_value(kind, "item type", &["note", "nt", "folder", "fd"]);
                    return None;
                }
            };
            Some((item_kind, name.clone(), vault_name.clone()))
        }
        _ => {
            print_unknown_argument(args.last().expect("extra arg"));
            None
        }
    }
}

fn parse_item_kind(value: &str, allow_vault: bool) -> Option<ItemKind> {
    match value {
        "vault" | "vl" if allow_vault => Some(ItemKind::Vault),
        "note" | "nt" => Some(ItemKind::Note),
        "folder" | "fd" => Some(ItemKind::Folder),
        _ => None,
    }
}

fn parse_list_filter(value: &str) -> Option<ListFilter> {
    match value {
        "note" | "nt" => Some(ListFilter::Note),
        "folder" | "fd" => Some(ListFilter::Folder),
        _ => None,
    }
}

fn missing_for_count(count: usize, required: &[&str], usage: &[&str]) -> u8 {
    let missing = if count >= required.len() {
        Vec::new()
    } else {
        required[count..].to_vec()
    };
    print_missing_required(&missing, usage);
    2
}

fn print_missing_required(missing: &[&str], usage: &[&str]) {
    eprintln!("error: The following required arguments were not provided:");
    for item in missing {
        eprintln!("    <{item}>");
    }
    eprintln!();
    eprintln!("USAGE:");
    for line in usage {
        eprintln!("    {line}");
    }
    eprintln!();
    eprintln!("For more information try --help");
}

fn print_invalid_value(value: &str, arg_name: &str, options: &[&str]) {
    eprintln!("error: \"{value}\" isn't a valid value for '<{arg_name}>'");
    eprintln!("\t[possible values: {}]", options.join(", "));
    eprintln!();
    eprintln!("For more information try --help");
}

fn print_unknown_top_level(value: &str) {
    eprintln!(
        "error: Found argument '{value}' which wasn't expected, or isn't valid in this context"
    );
    if value.starts_with('-') {
        eprintln!();
        eprintln!(
            "\tIf you tried to supply `{value}` as a value rather than a flag, use `-- {value}`"
        );
    }
    eprintln!();
    eprintln!("USAGE:");
    eprintln!("    executable <SUBCOMMAND>");
    eprintln!();
    eprintln!("For more information try --help");
}

fn print_unknown_argument(value: &str) {
    eprintln!(
        "error: Found argument '{value}' which wasn't expected, or isn't valid in this context"
    );
    eprintln!();
    eprintln!("USAGE:");
    eprintln!("    executable <SUBCOMMAND>");
    eprintln!();
    eprintln!("For more information try --help");
}

fn runtime_error(message: impl AsRef<str>) {
    eprintln!("{RED}error{RESET}: {}", message.as_ref());
}

fn blue(value: &str) -> String {
    format!("{BLUE}{value}{RESET}")
}

fn canonical_command(value: &str) -> Option<Cmd> {
    match value {
        "vault" | "vl" => Some(Cmd::Vault),
        "enter" | "en" => Some(Cmd::Enter),
        "note" | "nt" => Some(Cmd::Note),
        "folder" | "fd" => Some(Cmd::Folder),
        "open" | "op" => Some(Cmd::Open),
        "opdir" | "od" => Some(Cmd::OpDir),
        "chdir" | "cd" => Some(Cmd::Chdir),
        "list" | "ls" => Some(Cmd::List),
        "remove" | "rm" => Some(Cmd::Remove),
        "rename" | "rn" => Some(Cmd::Rename),
        "move" | "mv" => Some(Cmd::Move),
        "vmove" | "vm" => Some(Cmd::VMove),
        "config" | "cf" => Some(Cmd::Config),
        _ => None,
    }
}

fn command_help(cmd: Cmd) -> &'static str {
    match cmd {
        Cmd::Vault => VAULT_HELP,
        Cmd::Enter => ENTER_HELP,
        Cmd::Note => NOTE_HELP,
        Cmd::Folder => FOLDER_HELP,
        Cmd::Open => OPEN_HELP,
        Cmd::OpDir => OPDIR_HELP,
        Cmd::Chdir => CHDIR_HELP,
        Cmd::List => LIST_HELP,
        Cmd::Remove => REMOVE_HELP,
        Cmd::Rename => RENAME_HELP,
        Cmd::Move => MOVE_HELP,
        Cmd::VMove => VMOVE_HELP,
        Cmd::Config => CONFIG_HELP,
    }
}

