fn exact_slice<const N: usize>(values: &[String]) -> Option<[String; N]> {
    if values.len() != N {
        return None;
    }
    Some(std::array::from_fn(|index| values[index].clone()))
}

fn write_config(path: &Path, config: &Config) -> io::Result<()> {
    let content = format!(
        "editor = '{}'\nconflict = {}\n",
        config.editor, config.conflict
    );
    fs::write(path, content)
}

fn read_config(path: &Path) -> io::Result<Config> {
    let content = fs::read_to_string(path)?;
    let mut config = Config::default();
    for line in content.lines() {
        if let Some(value) = parse_single_quoted(line, "editor") {
            config.editor = value;
        } else if let Some(value) = parse_bool_value(line, "conflict") {
            config.conflict = value;
        }
    }
    Ok(config)
}

fn write_vaults(path: &Path, vaults: &VaultStore) -> io::Result<()> {
    let mut content = String::new();
    if let Some(current) = &vaults.current {
        content.push_str(&format!("current = '{current}'\n\n"));
    }
    content.push_str("[vaults]\n");
    for entry in &vaults.entries {
        content.push_str(&format!("{} = '{}'\n", entry.name, entry.location));
    }
    fs::write(path, content)
}

fn read_vaults(path: &Path) -> io::Result<VaultStore> {
    let content = fs::read_to_string(path)?;
    let mut store = VaultStore::default();
    let mut in_vaults = false;
    for line in content.lines() {
        if line == "[vaults]" {
            in_vaults = true;
            continue;
        }
        if !in_vaults {
            if let Some(value) = parse_single_quoted(line, "current") {
                store.current = Some(value);
            }
            continue;
        }
        if let Some((name, location)) = parse_mapping(line) {
            store.entries.push(VaultEntry { name, location });
        }
    }
    Ok(store)
}

fn write_vault_data(path: &Path, data: &VaultData) -> io::Result<()> {
    let content = format!(
        "name = '{}'\nlocation = '{}'\nfolder = '{}'\nhistory = []\n",
        data.name, data.location, data.folder
    );
    fs::write(path, content)
}

fn save_vault_data(entry: &VaultEntry, data: &VaultData) -> io::Result<()> {
    let data_path = PathBuf::from(&entry.location)
        .join(&entry.name)
        .join(".jot")
        .join("data");
    write_vault_data(&data_path, data)
}

fn read_vault_data(path: &Path) -> io::Result<VaultData> {
    let content = fs::read_to_string(path)?;
    let mut data = VaultData {
        name: String::new(),
        location: String::new(),
        folder: String::new(),
    };
    for line in content.lines() {
        if let Some(value) = parse_single_quoted(line, "name") {
            data.name = value;
        } else if let Some(value) = parse_single_quoted(line, "location") {
            data.location = value;
        } else if let Some(value) = parse_single_quoted(line, "folder") {
            data.folder = value;
        }
    }
    Ok(data)
}

fn parse_single_quoted(line: &str, key: &str) -> Option<String> {
    let prefix = format!("{key} = '");
    let remainder = line.strip_prefix(&prefix)?;
    let value = remainder.strip_suffix('\'')?;
    Some(value.to_string())
}

fn parse_bool_value(line: &str, key: &str) -> Option<bool> {
    let prefix = format!("{key} = ");
    let remainder = line.strip_prefix(&prefix)?;
    match remainder {
        "true" => Some(true),
        "false" => Some(false),
        _ => None,
    }
}

fn parse_mapping(line: &str) -> Option<(String, String)> {
    let (key, value) = line.split_once(" = ")?;
    let value = value.strip_prefix('\'')?.strip_suffix('\'')?;
    Some((key.to_string(), value.to_string()))
}

unsafe extern "C" {
    fn getuid() -> c_uint;
    fn getpwuid(uid: c_uint) -> *mut Passwd;
}

#[repr(C)]
struct Passwd {
    pw_name: *mut c_char,
    pw_passwd: *mut c_char,
    pw_uid: c_uint,
    pw_gid: c_uint,
    pw_gecos: *mut c_char,
    pw_dir: *mut c_char,
    pw_shell: *mut c_char,
}

fn real_home_dir() -> io::Result<PathBuf> {
    unsafe {
        let passwd = getpwuid(getuid());
        if passwd.is_null() {
            return Err(io::Error::new(
                io::ErrorKind::NotFound,
                "home directory not found",
            ));
        }
        let home = CStr::from_ptr((*passwd).pw_dir)
            .to_string_lossy()
            .into_owned();
        Ok(PathBuf::from(home))
    }
}

